func:
// ======================================================
// NODE: Fronius Werte auswerten
// Zweck:
// - Fronius PowerFlow API auswerten
// - SOC, Hauslast, PV-Leistung und Batterie-Leistung lesen
// - Werte zusätzlich im flow-Speicher ablegen
// - Keine node.warn Ausgaben: Debug nur über Debug-Node
// ======================================================

const data = msg.payload?.Body?.Data;
const site = data?.Site || {};
const inverters = data?.Inverters || {};

// Ersten Inverter suchen
const firstInvKey = Object.keys(inverters)[0];
const inv = firstInvKey ? inverters[firstInvKey] : {};

// Rohwerte aus Fronius API
const soc = Number(inv.SOC);
const batteryMode = inv.Battery_Mode ?? null;

const pPv = Number(site.P_PV ?? 0);
const pLoadRaw = Number(site.P_Load ?? 0);
const pGrid = Number(site.P_Grid ?? 0);
const pAkkuRaw = Number(site.P_Akku ?? 0);

// Fronius P_Load ist häufig negativ für Verbrauch.
// Für unsere Logik wollen wir Hausverbrauch positiv in W.
const houseLoadW = Math.abs(pLoadRaw);

// V5/Victron-Anzeige-Konvention aus unserer PDF:
// Laden positiv, Entladen negativ.
// Fronius P_Akku muss ggf. später geprüft werden.
// Aktuell übernehmen wir den Rohwert separat und berechnen Anzeige konservativ.
const batteryPowerRawW = pAkkuRaw;
const batteryPowerDisplayW = pAkkuRaw;

// Validierung
const socValid = Number.isFinite(soc);
const houseLoadValid = Number.isFinite(houseLoadW);

// In flow-Speicher schreiben
if (socValid) {
    flow.set("soc_percent", soc);
}

if (houseLoadValid) {
    flow.set("house_load_w", houseLoadW);
}

flow.set("pv_power_w", Number.isFinite(pPv) ? pPv : 0);
flow.set("grid_power_w", Number.isFinite(pGrid) ? pGrid : 0);
flow.set("battery_power_raw_w", Number.isFinite(batteryPowerRawW) ? batteryPowerRawW : 0);
flow.set("battery_mode", batteryMode);

// Debug-/Status-Payload
msg.payload = {
    ok: socValid && houseLoadValid,
    source: "fronius_powerflow",
    soc_percent: socValid ? soc : null,
    battery_mode: batteryMode,
    house_load_w: houseLoadValid ? houseLoadW : null,
    pv_power_w: Number.isFinite(pPv) ? pPv : null,
    grid_power_w: Number.isFinite(pGrid) ? pGrid : null,
    battery_power_raw_w: Number.isFinite(batteryPowerRawW) ? batteryPowerRawW : null,
    battery_power_display_w: Number.isFinite(batteryPowerDisplayW) ? batteryPowerDisplayW : null,
    raw: {
        P_Load: pLoadRaw,
        P_Grid: pGrid,
        P_Akku: pAkkuRaw,
        P_PV: pPv
    }
};

return msg;

// ======================================================
// NODE: Verto_HTTP_auswerten
// Zweck:
// - Fronius PowerFlowRealtimeData auswerten
// - P_Grid, P_Load, P_PV, P_Akku und SOC robust extrahieren
// - Werte im flow context speichern
// - KEINE Regelentscheidung hier
// ======================================================

const DEBUG = true;

// ------------------------------------------------------
// Hilfsfunktionen
// ------------------------------------------------------
function asNumber(v) {
    if (v === null || v === undefined) return null;
    const n = Number(v);
    return Number.isFinite(n) ? n : null;
}

function pickNumber(...values) {
    for (const v of values) {
        const n = asNumber(v);
        if (n !== null) return n;
    }
    return null;
}

// ------------------------------------------------------
// Fronius PowerFlow Struktur
// ------------------------------------------------------
const data = msg.payload?.Body?.Data || {};
const site = data.Site || {};
const inverters = data.Inverters || {};

// Meist gibt es nur Inverter "1"
const inv1 =
    inverters["1"] ||
    inverters[1] ||
    Object.values(inverters)[0] ||
    {};

// ------------------------------------------------------
// Werte lesen
// ------------------------------------------------------

// P_Grid:
// typischerweise:
//   > 0 = Netzbezug
//   < 0 = Einspeisung
const gridPowerW = pickNumber(
    site.P_Grid,
    msg.grid_power_w,
    msg.payload?.grid_power_w
);

// P_Load:
// bei Fronius oft negativ, wir speichern Hausverbrauch positiv
const pLoadRaw = pickNumber(
    site.P_Load,
    msg.house_load_w,
    msg.payload?.house_load_w
);

const houseLoadW = pLoadRaw !== null ? Math.abs(pLoadRaw) : null;

const pvPowerW = pickNumber(
    site.P_PV,
    msg.pv_power_w,
    msg.payload?.pv_power_w
);

// P_Akku / P_Battery:
// Vorzeichen kann je nach Fronius-Ansicht unterschiedlich sein.
// Wir speichern erstmal roh und ändern NICHTS blind.
const batteryPowerRawW = pickNumber(
    site.P_Akku,
    site.P_Battery,
    msg.battery_power_raw_w,
    msg.payload?.battery_power_raw_w
);

// SOC kann je nach Endpoint im Inverter-Block oder Site liegen
const socPercent = pickNumber(
    inv1.SOC,
    site.SOC,
    msg.soc_percent,
    msg.payload?.soc_percent
);

// Battery Mode, falls vorhanden
const batteryMode =
    inv1.Battery_Mode ||
    inv1.battery_mode ||
    site.Battery_Mode ||
    msg.battery_mode ||
    msg.payload?.battery_mode ||
    null;

// ------------------------------------------------------
// Plausibilitätscheck
// ------------------------------------------------------
if (gridPowerW === null) {
    node.error("P_Grid / grid_power_w nicht gefunden", msg);
    return null;
}

if (houseLoadW === null) {
    node.warn("P_Load / house_load_w nicht gefunden, Regelung kann später nur mit P_Grid arbeiten");
}

// ------------------------------------------------------
// flow context speichern
// ------------------------------------------------------
flow.set("fronius_grid_power_w", gridPowerW);
flow.set("fronius_house_load_w", houseLoadW);
flow.set("fronius_pv_power_w", pvPowerW);
flow.set("fronius_battery_power_raw_w", batteryPowerRawW);
flow.set("fronius_soc_percent", socPercent);
flow.set("fronius_battery_mode", batteryMode);
flow.set("fronius_http_last_seen", Date.now());

// Für spätere Functions auch auf msg schreiben
msg.ok = true;
msg.source = "fronius_powerflow";

msg.grid_power_w = gridPowerW;
msg.house_load_w = houseLoadW;
msg.pv_power_w = pvPowerW;
msg.battery_power_raw_w = batteryPowerRawW;
msg.soc_percent = socPercent;
msg.battery_mode = batteryMode;

if (DEBUG) {
    msg.debug_fronius = {
        grid_power_w: gridPowerW,
        grid_meaning:
            gridPowerW > 0 ? "Netzbezug" :
            gridPowerW < 0 ? "Einspeisung" :
            "Null",
        house_load_w: houseLoadW,
        pv_power_w: pvPowerW,
        battery_power_raw_w: batteryPowerRawW,
        soc_percent: socPercent,
        battery_mode: batteryMode,
        last_seen: new Date().toISOString()
    };
}

return msg;

// ======================================================
// NODE: Forecast_auswerten_V6
// Zweck:
// - forecast.solar Response auswerten
// - result.watt_hours_period pro Europe/Vienna-Kalendertag summieren
// - heute, morgen, übermorgen in kWh berechnen
// - Werte im flow-Speicher ablegen
// - V6: noch keine finale Steuerentscheidung, nur Forecast-Daten
// ======================================================

function viennaDateString(offsetDays = 0) {
    const fmt = new Intl.DateTimeFormat("sv-SE", {
        timeZone: "Europe/Vienna",
        year: "numeric",
        month: "2-digit",
        day: "2-digit"
    });

    const now = new Date();
    const todayStr = fmt.format(now);

    // Mittagszeit verhindert DST-/Zeitzonen-Kantenprobleme
    const base = new Date(`${todayStr}T12:00:00`);
    base.setDate(base.getDate() + offsetDays);

    return fmt.format(base);
}

function round1(x) {
    return Math.round(x * 10) / 10;
}

function sumWhForDate(wattHoursPeriod, dateStr) {
    let sumWh = 0;
    let points = 0;

    for (const [ts, whRaw] of Object.entries(wattHoursPeriod || {})) {
        if (!ts.startsWith(dateStr)) continue;

        const wh = Number(whRaw);
        if (!Number.isFinite(wh)) continue;

        sumWh += wh;
        points++;
    }

    return {
        kwh: round1(sumWh / 1000),
        points
    };
}

// Payload robust behandeln
let payload = msg.payload;

if (typeof payload === "string") {
    try {
        payload = JSON.parse(payload);
    } catch (e) {
        payload = {};
    }
}

const whPeriod = payload?.result?.watt_hours_period;

const todayDate = viennaDateString(0);
const tomorrowDate = viennaDateString(1);
const dayAfterTomorrowDate = viennaDateString(2);

let source = "forecast.solar/watt_hours_period";
let usedFallback = false;

let today = { kwh: 0, points: 0 };
let tomorrow = { kwh: 0, points: 0 };
let dayAfterTomorrow = { kwh: 0, points: 0 };

if (whPeriod && typeof whPeriod === "object") {
    today = sumWhForDate(whPeriod, todayDate);
    tomorrow = sumWhForDate(whPeriod, tomorrowDate);
    dayAfterTomorrow = sumWhForDate(whPeriod, dayAfterTomorrowDate);

    if (today.points + tomorrow.points + dayAfterTomorrow.points === 0) {
        usedFallback = true;
        source = "fallback_no_matching_dates";
    }
} else {
    usedFallback = true;
    source = "fallback_missing_watt_hours_period";
}

// Flow-Speicher für Strategie_V6
flow.set("forecast_today_kwh", today.kwh);
flow.set("forecast_tomorrow_kwh", tomorrow.kwh);
flow.set("forecast_day_after_tomorrow_kwh", dayAfterTomorrow.kwh);

flow.set("forecast_today_date", todayDate);
flow.set("forecast_tomorrow_date", tomorrowDate);
flow.set("forecast_day_after_tomorrow_date", dayAfterTomorrowDate);

flow.set("forecast_source", source);
flow.set("forecast_used_fallback", usedFallback);
flow.set("forecast_updated_at", new Date().toISOString());

// Abwärtskompatibel für alte Nodes
flow.set("forecast_kwh", today.kwh);
flow.set("forecast_date", todayDate);

// Debug-Ausgabe
msg.payload = {
    ok: !usedFallback,
    source,
    used_fallback: usedFallback,
    forecast: {
        today: {
            date: todayDate,
            kwh: today.kwh,
            points: today.points
        },
        tomorrow: {
            date: tomorrowDate,
            kwh: tomorrow.kwh,
            points: tomorrow.points
        },
        day_after_tomorrow: {
            date: dayAfterTomorrowDate,
            kwh: dayAfterTomorrow.kwh,
            points: dayAfterTomorrow.points
        }
    }
};

return msg;

// ======================================================
// Strategie_V7.3 FINAL
//
// RESERVE / ZIEL-SOC:
//
// HEUTE und MORGEN werden mit denselben Schwellen
// klassifiziert.
//
// SONDERREGEL:
// Wenn HEUTE = GOOD:
// → GOOD-Ziel-SOC gilt unabhängig von MORGEN.
//
// Wenn HEUTE != GOOD:
// → schlechtere Klasse aus HEUTE und MORGEN entscheidet.
//
// LADEBLOCK:
// → nur Forecast HEUTE
//
// LADEBEGRENZUNG:
// → nur Forecast HEUTE
//
// STRATEGISCHE ENTLADUNG:
// Start = Sonnenaufgang - Offset
// Ende  = Sonnenaufgang + Offset
//
// ======================================================

const CONFIG_KEY =
    "strategy_v7_config";

const WRTE_MAX =
    10000;


// ======================================================
// HILFSFUNKTIONEN
// ======================================================

const clamp =
    (v, min, max) =>
        Math.min(
            Math.max(
                Number(v),
                min
            ),
            max
        );


const round0 =
    v =>
        Math.round(
            Number(v) || 0
        );


const round1 =
    v =>
        Math.round(
            Number(v) * 10
        ) / 10;


const normMin =
    v =>
        (
            (
                Math.round(
                    Number(v) || 0
                ) %
                1440
            ) +
            1440
        ) %
        1440;


const hhmm =
    v => {

        const m =
            normMin(v);

        return (
            String(
                Math.floor(
                    m / 60
                )
            )
            .padStart(
                2,
                "0"
            )
            +
            ":"
            +
            String(
                m % 60
            )
            .padStart(
                2,
                "0"
            )
        );
    };


const inWindow =
    (
        now,
        start,
        end
    ) => {

        now =
            normMin(now);

        start =
            normMin(start);

        end =
            normMin(end);


        if (
            start === end
        ) {
            return false;
        }


        return (
            start < end
        )

            ? (
                now >= start &&
                now < end
            )

            : (
                now >= start ||
                now < end
            );
    };


const minUntil =
    (
        now,
        end
    ) => {

        let d =
            normMin(end) -
            normMin(now);


        if (
            d < 0
        ) {
            d +=
                1440;
        }


        return d;
    };


// ======================================================
// WIEN ZEIT
// ======================================================

function viennaMinutes() {

    const t =
        new Intl.DateTimeFormat(
            "sv-SE",
            {
                timeZone:
                    "Europe/Vienna",

                hour:
                    "2-digit",

                minute:
                    "2-digit",

                hour12:
                    false
            }
        )
        .format(
            new Date()
        );


    const [
        h,
        m
    ] =
        t
        .split(":")
        .map(
            Number
        );


    return (
        h * 60 +
        m
    );
}


function viennaDateTime() {

    return (
        new Intl.DateTimeFormat(
            "sv-SE",
            {
                timeZone:
                    "Europe/Vienna",

                year:
                    "numeric",

                month:
                    "2-digit",

                day:
                    "2-digit",

                hour:
                    "2-digit",

                minute:
                    "2-digit",

                second:
                    "2-digit",

                hour12:
                    false
            }
        )
        .format(
            new Date()
        )
        .replace(
            " ",
            "T"
        )
    );
}


function viennaDateParts() {

    const parts =
        new Intl.DateTimeFormat(
            "en-CA",
            {
                timeZone:
                    "Europe/Vienna",

                year:
                    "numeric",

                month:
                    "2-digit",

                day:
                    "2-digit"
            }
        )
        .formatToParts(
            new Date()
        );


    const x =
        {};


    for (
        const p
        of parts
    ) {

        if (
            p.type !==
            "literal"
        ) {

            x[p.type] =
                Number(
                    p.value
                );
        }
    }


    return {

        year:
            x.year,

        month:
            x.month,

        day:
            x.day
    };
}


// ======================================================
// SONNENAUFGANG
// ======================================================

const d2r =
    v =>
        v *
        Math.PI /
        180;


const r2d =
    v =>
        v *
        180 /
        Math.PI;


const normDeg =
    v =>
        (
            (v % 360) +
            360
        ) %
        360;


function dayOfYear(
    year,
    month,
    day
) {

    return Math.floor(

        (
            Date.UTC(
                year,
                month - 1,
                day
            )
            -
            Date.UTC(
                year,
                0,
                0
            )
        )

        /

        86400000
    );
}


function sunriseUTC(
    year,
    month,
    day,
    lat,
    lon
) {

    if (
        !Number.isFinite(lat) ||
        !Number.isFinite(lon)
    ) {
        return null;
    }


    const n =
        dayOfYear(
            year,
            month,
            day
        );


    const lngHour =
        lon /
        15;


    const t =
        n +
        (
            (
                6 -
                lngHour
            )
            /
            24
        );


    const M =
        0.9856 *
        t -
        3.289;


    const L =
        normDeg(

            M +

            1.916 *
            Math.sin(
                d2r(M)
            )

            +

            0.020 *
            Math.sin(
                d2r(
                    2 *
                    M
                )
            )

            +

            282.634
        );


    let RA =
        normDeg(

            r2d(

                Math.atan(

                    0.91764 *

                    Math.tan(
                        d2r(L)
                    )
                )
            )
        );


    RA +=

        Math.floor(
            L /
            90
        ) *
        90

        -

        Math.floor(
            RA /
            90
        ) *
        90;


    RA /=
        15;


    const sinDec =
        0.39782 *
        Math.sin(
            d2r(L)
        );


    const cosDec =
        Math.cos(
            Math.asin(
                sinDec
            )
        );


    const cosH =

        (
            Math.cos(
                d2r(
                    90.833
                )
            )

            -

            sinDec *
            Math.sin(
                d2r(lat)
            )
        )

        /

        (
            cosDec *

            Math.cos(
                d2r(lat)
            )
        );


    if (
        cosH > 1 ||
        cosH < -1
    ) {
        return null;
    }


    const H =

        (
            360 -

            r2d(
                Math.acos(
                    cosH
                )
            )
        )

        /

        15;


    const localMeanTime =

        H +
        RA -
        0.06571 *
        t -
        6.622;


    let utcHour =
        localMeanTime -
        lngHour;


    while (
        utcHour < 0
    ) {

        utcHour +=
            24;
    }


    while (
        utcHour >= 24
    ) {

        utcHour -=
            24;
    }


    return new Date(

        Date.UTC(
            year,
            month - 1,
            day
        )

        +

        utcHour *
        3600000
    );
}


function dateToViennaMinutes(
    date
) {

    if (
        !(date instanceof Date) ||
        Number.isNaN(
            date.getTime()
        )
    ) {
        return null;
    }


    const t =
        new Intl.DateTimeFormat(
            "sv-SE",
            {
                timeZone:
                    "Europe/Vienna",

                hour:
                    "2-digit",

                minute:
                    "2-digit",

                hour12:
                    false
            }
        )
        .format(
            date
        );


    const [
        h,
        m
    ] =
        t
        .split(":")
        .map(
            Number
        );


    return (
        h * 60 +
        m
    );
}


// ======================================================
// CONFIG LADEN
// ======================================================

const cfg =
    flow.get(
        CONFIG_KEY
    );


if (
    !cfg ||
    typeof cfg !==
    "object"
) {

    msg.payload = {

        ok:
            false,

        error:
            "strategy_v7_config fehlt",

        modbus_proposal: {

            write_active:
                true,

            storctl_mod:
                0,

            outwrte:
                10000,

            inwrte:
                10000,

            mode_reason:
                "config_missing_verto_free"
        },

        write: {

            storctl_mod:
                0,

            outwrte:
                10000,

            inwrte:
                10000
        }
    };


    node.status({

        fill:
            "red",

        shape:
            "ring",

        text:
            "V7 Config fehlt → Verto frei"
    });


    return msg;
}


// ======================================================
// SIMULATION
// ======================================================

const sim =
    msg.payload?.sim ===
    true;


const si =
    sim
        ? msg.payload
        : {};


// ======================================================
// BATTERIE
// ======================================================

const BATTERY_CAPACITY_KWH =
    Number(
        cfg.battery.capacity_kwh
    );


const BATTERY_POWER_REF_W =
    Number(
        cfg.battery.power_ref_w
    );


// ======================================================
// STRATEGISCHE ENTLADUNG
// ======================================================

const DISCHARGE_ENABLED =
    cfg.discharge.enabled ===
    true;


const DISCHARGE_OFFSET_MIN =
    Number(
        cfg.discharge.sunrise_offset_min
    );


const DISCHARGE_END_OFFSET_MIN =
    Number(
        cfg.discharge.sunrise_end_offset_min
        ??
        0
    );


const MAX_DISCHARGE_POWER_W =
    Number(
        cfg.discharge.max_power_w
    );


const SOC_MARGIN =
    Number(
        cfg.discharge.soc_margin_percent
        ??
        0
    );


const FALLBACK_START =
    Number(
        cfg.discharge.fallback_start_min
        ??
        270
    );


const FALLBACK_END =
    Number(
        cfg.discharge.fallback_end_min
        ??
        480
    );


// ======================================================
// LADEBLOCK
// ======================================================

const CHARGE_BLOCK_ENABLED =
    cfg.charge_block.enabled ===
    true;


const CHARGE_BLOCK_DURATION =
    Number(
        cfg.charge_block.duration_min
    );


const CHARGE_BLOCK_SOC_MARGIN =
    Number(
        cfg.charge_block.min_soc_above_target
    );


const CHARGE_BLOCK_MIN_TODAY =
    Number(
        cfg.charge_block.min_today_kwh
    );


// ======================================================
// RESERVE V7.3
// ======================================================

const MIN_SOC =
    Number(
        cfg.reserve.min_soc_absolute
    );


const VERY_BAD_BELOW =
    Number(
        cfg.reserve.very_bad_below_kwh
        ??
        15
    );


const TARGET_VERY_BAD =
    Number(
        cfg.reserve.target_soc_very_bad
        ??
        80
    );


const WEAK_BELOW =
    Number(
        cfg.reserve.weak_below_kwh
        ??
        30
    );


const TARGET_WEAK =
    Number(
        cfg.reserve.target_soc_weak
        ??
        50
    );


const MEDIUM_BELOW =
    Number(
        cfg.reserve.medium_below_kwh
        ??
        45
    );


const TARGET_MEDIUM =
    Number(
        cfg.reserve.target_soc_medium
        ??
        20
    );


const TARGET_GOOD =
    Number(
        cfg.reserve.target_soc_good
        ??
        10
    );


// ======================================================
// LADEBEGRENZUNG
// ======================================================

const CHARGE_LIMIT_ENABLED =
    cfg.charge_limit.enabled ===
    true;


const VERY_GOOD_TODAY =
    Number(
        cfg.charge_limit.very_good_today_min_kwh
    );


const VERY_GOOD_PERCENT =
    Number(
        cfg.charge_limit.very_good_percent
    );


const GOOD_TODAY =
    Number(
        cfg.charge_limit.good_today_min_kwh
    );


const GOOD_PERCENT =
    Number(
        cfg.charge_limit.good_percent
    );


const MEDIUM_TODAY =
    Number(
        cfg.charge_limit.medium_today_min_kwh
    );


const MEDIUM_PERCENT =
    Number(
        cfg.charge_limit.medium_percent
    );


const WEAK_PERCENT =
    Number(
        cfg.charge_limit.weak_percent
    );


// ======================================================
// HAUSLAST
// ======================================================

const HOUSE_LOAD_ENABLED =
    cfg.house_load.enabled ===
    true;


const HOUSE_LOAD_MIN_SOC =
    Number(
        cfg.house_load.min_soc
    );


const HOUSE_LOAD_MARGIN_W =
    Number(
        cfg.house_load.export_margin_w
    );


const wattsToWrte =
    w =>
        clamp(

            Math.round(

                Number(w) /
                BATTERY_POWER_REF_W *
                WRTE_MAX
            ),

            0,

            WRTE_MAX
        );


const wrteToWatts =
    w =>
        Math.round(

            Number(w) /
            WRTE_MAX *
            BATTERY_POWER_REF_W
        );


// ======================================================
// ZEIT / SONNENAUFGANG
// ======================================================

const nowMinutes =

    sim &&

    Number.isFinite(
        Number(
            si.vienna_minutes
        )
    )

        ? normMin(
            si.vienna_minutes
        )

        : viennaMinutes();


let sunriseMinutes =
    null;


let sunriseSource =
    "fallback";


if (

    sim &&

    Number.isFinite(
        Number(
            si.sunrise_minutes
        )
    )

) {

    sunriseMinutes =
        normMin(
            si.sunrise_minutes
        );


    sunriseSource =
        "simulation";
}

else {

    const lat =
        Number(
            cfg.location?.latitude
        );


    const lon =
        Number(
            cfg.location?.longitude
        );


    const locationValid =

        cfg.location?.latitude !==
        null

        &&

        cfg.location?.longitude !==
        null

        &&

        Number.isFinite(
            lat
        )

        &&

        Number.isFinite(
            lon
        );


    if (
        locationValid
    ) {

        const d =
            viennaDateParts();


        sunriseMinutes =
            dateToViennaMinutes(

                sunriseUTC(
                    d.year,
                    d.month,
                    d.day,
                    lat,
                    lon
                )
            );


        if (
            sunriseMinutes !==
            null
        ) {

            sunriseSource =
                "calculated";
        }
    }
}


// ======================================================
// ENTLADEFENSTER
// ======================================================

const dischargeStart =

    sunriseMinutes !==
    null

        ? normMin(
            sunriseMinutes -
            DISCHARGE_OFFSET_MIN
        )

        : FALLBACK_START;


const dischargeEnd =

    sunriseMinutes !==
    null

        ? normMin(
            sunriseMinutes +
            DISCHARGE_END_OFFSET_MIN
        )

        : normMin(
            FALLBACK_END +
            DISCHARGE_END_OFFSET_MIN
        );


const inDischargeWindow =

    DISCHARGE_ENABLED &&

    inWindow(
        nowMinutes,
        dischargeStart,
        dischargeEnd
    );


// ======================================================
// LADEBLOCK-ZEITFENSTER
// ======================================================

const chargeBlockStart =

    sunriseMinutes !==
    null

        ? sunriseMinutes

        : FALLBACK_END;


const chargeBlockEnd =
    normMin(

        chargeBlockStart +
        CHARGE_BLOCK_DURATION
    );


const inChargeBlockWindow =

    CHARGE_BLOCK_ENABLED &&

    inWindow(
        nowMinutes,
        chargeBlockStart,
        chargeBlockEnd
    );


// ======================================================
// EXTERNE ENTLADE-SPERRE
// ======================================================

const entladenSperren =

    msg.entladen_sperren ===
    true

    ||

    msg.payload?.entladen_sperren ===
    true

    ||

    flow.get(
        "verto_discharge_lock"
    ) ===
    true;


const lockSources =

    flow.get(
        "verto_discharge_lock_sources"
    )

    ||

    (
        msg.lock_source
            ? [
                msg.lock_source
            ]
            : []
    );


const allLocks =

    flow.get(
        "verto_discharge_locks"
    )

    ||

    {};


if (
    entladenSperren
) {

    const M =
        0;

    const O =
        10000;

    const I =
        10000;


    if (
        !sim
    ) {

        flow.set(
            "strategy_v7_external_discharge_lock_active",
            true
        );

        flow.set(
            "strategy_v7_strategic_discharge_allowed",
            false
        );

        flow.set(
            "strategy_v7_house_load_battery_allowed",
            false
        );

        flow.set(
            "strategy_v7_charge_block_allowed",
            false
        );

        flow.set(
            "strategy_v7_charge_limit_is_active",
            false
        );

        flow.set(
            "storctl_mod",
            M
        );

        flow.set(
            "outwrte",
            O
        );

        flow.set(
            "inwrte",
            I
        );
    }


    msg.payload = {

        ok:
            true,

        mode:
            sim
                ? "simulation_v7_external_discharge_lock"
                : "v7_external_discharge_lock",

        simulation: {

            active:
                sim
        },

        external_discharge_lock: {

            active:
                true,

            sources:
                lockSources,

            all_locks:
                allLocks,

            reason:
                "entladen_sperren_aktiv"
        },

        time: {

            hhmm:
                hhmm(
                    nowMinutes
                ),

            sunrise:
                sunriseMinutes ===
                null

                    ? null

                    : hhmm(
                        sunriseMinutes
                    ),

            sunrise_source:
                sunriseSource,

            discharge_start:
                hhmm(
                    dischargeStart
                ),

            discharge_end:
                hhmm(
                    dischargeEnd
                ),

            discharge_end_offset_min:
                DISCHARGE_END_OFFSET_MIN,

            charge_block_start:
                hhmm(
                    chargeBlockStart
                ),

            charge_block_end:
                hhmm(
                    chargeBlockEnd
                )
        },

        strategic_discharge: {

            allowed:
                false,

            reason:
                "external_discharge_lock"
        },

        house_load_battery: {

            allowed:
                false,

            reason:
                "external_discharge_lock"
        },

        charge_block: {

            allowed:
                false,

            reason:
                "external_discharge_lock"
        },

        charge_limit: {

            active:
                false,

            reason:
                "external_discharge_lock"
        },

        modbus_proposal: {

            write_active:
                !sim,

            storctl_mod:
                M,

            outwrte:
                O,

            inwrte:
                I,

            mode_reason:
                "external_discharge_lock_verto_free"
        },

        write: {

            storctl_mod:
                M,

            outwrte:
                O,

            inwrte:
                I
        }
    };


    node.status({

        fill:
            "red",

        shape:
            "ring",

        text:
            lockSources.length

                ? (
                    "Entladen gesperrt: " +
                    lockSources.join(
                        ", "
                    )
                )

                : "Entladen gesperrt"
    });


    return msg;
}


if (
    !sim
) {

    flow.set(
        "strategy_v7_external_discharge_lock_active",
        false
    );
}


// ======================================================
// FORECAST
// ======================================================

const todayKwh =

    sim &&

    Number.isFinite(
        Number(
            si.forecast_today_kwh
        )
    )

        ? Number(
            si.forecast_today_kwh
        )

        : Number(
            flow.get(
                "forecast_today_kwh"
            )
            ??
            0
        );


const tomorrowKwh =

    sim &&

    Number.isFinite(
        Number(
            si.forecast_tomorrow_kwh
        )
    )

        ? Number(
            si.forecast_tomorrow_kwh
        )

        : Number(
            flow.get(
                "forecast_tomorrow_kwh"
            )
            ??
            0
        );


const todayDate =
    flow.get(
        "forecast_today_date"
    )
    ??
    null;


const tomorrowDate =
    flow.get(
        "forecast_tomorrow_date"
    )
    ??
    null;


const forecastSource =
    flow.get(
        "forecast_source"
    )
    ??
    "unknown";


const forecastFallback =

    sim

        ? false

        : Boolean(
            flow.get(
                "forecast_used_fallback"
            )
        );


// ======================================================
// LIVE-WERTE
// ======================================================

const soc =

    sim

        ? Number(
            si.soc_percent
        )

        : Number(
            flow.get(
                "soc_percent"
            )
        );


const houseLoadW =

    sim

        ? Number(
            si.house_load_w
            ??
            0
        )

        : Number(
            flow.get(
                "house_load_w"
            )
            ??
            0
        );


const pvPowerW =

    sim

        ? Number(
            si.pv_power_w
            ??
            0
        )

        : Number(
            flow.get(
                "pv_power_w"
            )
            ??
            0
        );


const gridPowerW =

    sim

        ? Number(
            si.grid_power_w
            ??
            0
        )

        : Number(
            flow.get(
                "grid_power_w"
            )
            ??
            0
        );


const batteryMode =

    sim

        ? "simulation"

        : (
            flow.get(
                "battery_mode"
            )
            ??
            null
        );


const socValid =
    Number.isFinite(
        soc
    );


const houseLoadValid =
    Number.isFinite(
        houseLoadW
    );


const gridPowerValid =
    Number.isFinite(
        gridPowerW
    );


// ======================================================
// FORECAST-VALIDITÄT
// ======================================================

// Ladeblock + Ladebegrenzung:
// nur HEUTE.
const todayForecastValid =

    Number.isFinite(
        todayKwh
    )

    &&

    !forecastFallback;


// Reserve / Ziel-SOC:
// HEUTE + MORGEN.
const reserveForecastValid =

    Number.isFinite(
        todayKwh
    )

    &&

    Number.isFinite(
        tomorrowKwh
    )

    &&

    !forecastFallback;


// ======================================================
// RESERVE-KLASSIFIZIERUNG
// ======================================================

function getReserveForecastClass(
    kwh
) {

    if (
        kwh <
        VERY_BAD_BELOW
    ) {

        return {

            rank:
                3,

            name:
                "VERY_BAD",

            targetSoc:
                TARGET_VERY_BAD
        };
    }


    if (
        kwh <
        WEAK_BELOW
    ) {

        return {

            rank:
                2,

            name:
                "WEAK",

            targetSoc:
                TARGET_WEAK
        };
    }


    if (
        kwh <
        MEDIUM_BELOW
    ) {

        return {

            rank:
                1,

            name:
                "MEDIUM",

            targetSoc:
                TARGET_MEDIUM
        };
    }


    return {

        rank:
            0,

        name:
            "GOOD",

        targetSoc:
            TARGET_GOOD
    };
}


// ======================================================
// RESERVE / ZIEL-SOC V7.3 FINAL
//
// REGEL:
//
// HEUTE GOOD:
// → GOOD gewinnt IMMER.
//
// HEUTE NICHT GOOD:
// → schlechtere Klasse heute/morgen gewinnt.
//
// ======================================================

let reserveClass =
    "unknown";


let todayReserveClass =
    "unknown";


let tomorrowReserveClass =
    "unknown";


let targetSoc =
    80;


let reserveReason =
    "forecast_invalid_or_missing";


let todayGoodOverride =
    false;


if (
    reserveForecastValid
) {

    const todayReserve =
        getReserveForecastClass(
            todayKwh
        );


    const tomorrowReserve =
        getReserveForecastClass(
            tomorrowKwh
        );


    todayReserveClass =
        todayReserve.name;


    tomorrowReserveClass =
        tomorrowReserve.name;


    let combinedReserve;


    // --------------------------------------------------
    // HEUTE GOOD HAT VORRANG
    // --------------------------------------------------

    if (
        todayReserve.name ===
        "GOOD"
    ) {

        combinedReserve =
            todayReserve;


        todayGoodOverride =
            true;


        reserveReason =
            "today_good_allows_good_target_soc";
    }

    else {

        // --------------------------------------------------
        // HEUTE NICHT GOOD:
        // schlechtere Klasse entscheidet.
        // --------------------------------------------------

        combinedReserve =

            todayReserve.rank >=
            tomorrowReserve.rank

                ? todayReserve

                : tomorrowReserve;


        todayGoodOverride =
            false;


        reserveReason =
            "today_not_good_worse_class_of_today_and_tomorrow";
    }


    reserveClass =
        combinedReserve.name;


    targetSoc =
        combinedReserve.targetSoc;
}


targetSoc =
    clamp(
        targetSoc,
        MIN_SOC,
        100
    );


// ======================================================
// STRATEGISCHE ENTLADUNG
// ======================================================

let strategicAllowed =
    false;


let strategicReason =
    "not_evaluated";


let energyToTargetKwh =
    0;


let hoursUntilDischargeEnd =
    0;


let calculatedDischargeW =
    0;


let requiredDischargeW =
    0;


const socAboveTarget =

    socValid

        ? Math.max(
            0,
            soc -
            targetSoc
        )

        : 0;


if (
    !DISCHARGE_ENABLED
) {

    strategicReason =
        "strategic_discharge_disabled";
}

else if (
    !reserveForecastValid
) {

    strategicReason =
        "forecast_invalid_no_strategic_discharge";
}

else if (
    !socValid
) {

    strategicReason =
        "soc_missing_no_strategic_discharge";
}

else if (
    !inDischargeWindow
) {

    strategicReason =
        "outside_discharge_window";
}

else if (

    soc <=
    targetSoc +
    SOC_MARGIN

) {

    strategicReason =
        "target_soc_reached_stop_discharge";
}

else {

    hoursUntilDischargeEnd =

        Math.max(

            1,

            minUntil(
                nowMinutes,
                dischargeEnd
            )
        )

        /

        60;


    energyToTargetKwh =

        BATTERY_CAPACITY_KWH *

        socAboveTarget /

        100;


    calculatedDischargeW =

        energyToTargetKwh /

        hoursUntilDischargeEnd *

        1000;


    requiredDischargeW =

        Math.min(

            calculatedDischargeW,

            MAX_DISCHARGE_POWER_W,

            BATTERY_POWER_REF_W
        );


    if (
        requiredDischargeW >
        0
    ) {

        strategicAllowed =
            true;


        strategicReason =
            "dynamic_discharge_to_target_by_discharge_end";
    }
}


// ======================================================
// HAUSLAST-FLOOR
// ======================================================

let houseFloorAllowed =
    false;


let houseFloorReason =
    "not_evaluated";


let houseFloorW =
    0;


if (
    !strategicAllowed
) {

    houseFloorReason =
        "only_used_during_strategic_discharge";
}

else if (
    !HOUSE_LOAD_ENABLED
) {

    houseFloorReason =
        "strategic_house_load_floor_disabled";
}

else if (
    !socValid
) {

    houseFloorReason =
        "soc_missing";
}

else if (
    !houseLoadValid
) {

    houseFloorReason =
        "house_load_invalid";
}

else if (

    soc <=
    HOUSE_LOAD_MIN_SOC

) {

    houseFloorReason =
        "soc_below_house_load_min";
}

else if (
    houseLoadW <=
    0
) {

    houseFloorReason =
        "house_load_zero";
}

else {

    houseFloorAllowed =
        true;


    houseFloorReason =
        "strategic_discharge_not_below_house_load";


    houseFloorW =

        Math.max(

            0,

            houseLoadW +
            HOUSE_LOAD_MARGIN_W
        );
}


// ======================================================
// LADEBLOCK
//
// NUR HEUTE
// ======================================================

let chargeBlockAllowed =
    false;


let chargeBlockReason =
    "not_evaluated";


if (
    !CHARGE_BLOCK_ENABLED
) {

    chargeBlockReason =
        "charge_block_disabled";
}

else if (
    !todayForecastValid
) {

    chargeBlockReason =
        "forecast_invalid_no_charge_block";
}

else if (
    !socValid
) {

    chargeBlockReason =
        "soc_missing_no_charge_block";
}

else if (
    !inChargeBlockWindow
) {

    chargeBlockReason =
        "outside_charge_block_window";
}

else if (

    todayKwh <
    CHARGE_BLOCK_MIN_TODAY

) {

    chargeBlockReason =
        "today_forecast_too_low_no_charge_block";
}

else if (

    soc <=
    targetSoc +
    CHARGE_BLOCK_SOC_MARGIN

) {

    chargeBlockReason =
        "soc_too_low_no_charge_block";
}

else {

    chargeBlockAllowed =
        true;


    chargeBlockReason =
        "sunrise_charge_block_active";
}


// ======================================================
// LADEBEGRENZUNG
//
// NUR HEUTE
// ======================================================

let chargeClass =
    "WEAK";


let maxChargePercent =
    100;


let chargeLimitReason =
    "not_evaluated";


if (
    !CHARGE_LIMIT_ENABLED
) {

    chargeClass =
        "OFF";


    maxChargePercent =
        100;


    chargeLimitReason =
        "charge_limit_disabled";
}

else if (
    !todayForecastValid
) {

    chargeClass =
        "WEAK";


    maxChargePercent =
        100;


    chargeLimitReason =
        "forecast_invalid_charge_unlimited";
}

else if (

    todayKwh >=
    VERY_GOOD_TODAY

) {

    chargeClass =
        "VERY_GOOD";


    maxChargePercent =
        VERY_GOOD_PERCENT;


    chargeLimitReason =
        "very_good_forecast";
}

else if (

    todayKwh >=
    GOOD_TODAY

) {

    chargeClass =
        "GOOD";


    maxChargePercent =
        GOOD_PERCENT;


    chargeLimitReason =
        "good_forecast";
}

else if (

    todayKwh >=
    MEDIUM_TODAY

) {

    chargeClass =
        "MEDIUM";


    maxChargePercent =
        MEDIUM_PERCENT;


    chargeLimitReason =
        "medium_forecast";
}

else {

    chargeClass =
        "WEAK";


    maxChargePercent =
        WEAK_PERCENT;


    chargeLimitReason =
        "weak_forecast";
}


maxChargePercent =
    clamp(
        maxChargePercent,
        0,
        100
    );


const maxChargeWrte =
    Math.round(

        maxChargePercent *
        100
    );


const chargeLimitActive =

    CHARGE_LIMIT_ENABLED

    &&

    todayForecastValid

    &&

    maxChargeWrte <
    WRTE_MAX;


// ======================================================
// GESAMT-ENTLADUNG
// ======================================================

let totalDischargeW =
    0;


let totalOutwrte =
    0;


if (
    strategicAllowed
) {

    totalDischargeW =

        Math.max(

            requiredDischargeW,

            houseFloorAllowed
                ? houseFloorW
                : 0
        );


    totalDischargeW =
        clamp(

            totalDischargeW,

            0,

            BATTERY_POWER_REF_W
        );


    totalOutwrte =
        wattsToWrte(
            totalDischargeW
        );
}


// ======================================================
// MODBUS-PRIORITÄT
//
// 1. Strategische Entladung
// 2. Ladeblock
// 3. Ladebegrenzung
// 4. Fronius frei
// ======================================================

let storctl =
    0;


let outwrte =
    10000;


let inwrte =
    10000;


let modeReason =
    "verto_free_self_consumption_control";


if (

    strategicAllowed

    &&

    totalOutwrte >
    0

) {

    storctl =
        3;


    outwrte =
        totalOutwrte;


    inwrte =
        -totalOutwrte;


    modeReason =
        "forced_dynamic_discharge_to_target_by_discharge_end";
}

else if (
    chargeBlockAllowed
) {

    storctl =
        1;


    outwrte =
        10000;


    inwrte =
        0;


    modeReason =
        "charge_block_only_fronius_controls_discharge";
}

else if (
    chargeLimitActive
) {

    storctl =
        1;


    outwrte =
        10000;


    inwrte =
        maxChargeWrte;


    modeReason =
        "forecast_charge_limit_only_fronius_controls_discharge";
}


// ======================================================
// FLOW-WERTE
// ======================================================

if (
    !sim
) {

    const values = {

        reserve_class:
            reserveClass,

        reserve_today_class:
            todayReserveClass,

        reserve_tomorrow_class:
            tomorrowReserveClass,

        reserve_today_good_override:
            todayGoodOverride,

        target_soc:
            targetSoc,

        min_soc:
            targetSoc,

        strategic_discharge_allowed:
            strategicAllowed,

        house_load_battery_allowed:
            false,

        verto_self_consumption_control:
            !strategicAllowed,

        strategic_house_load_floor_allowed:
            houseFloorAllowed,

        strategic_house_load_floor_w:
            houseFloorW,

        charge_block_allowed:
            chargeBlockAllowed,

        required_target_discharge_w:
            requiredDischargeW,

        house_load_battery_w:
            houseFloorW,

        total_battery_discharge_w:
            totalDischargeW,

        total_outwrte:
            totalOutwrte,

        charge_limit_class:
            chargeClass,

        max_charge_wrte:
            maxChargeWrte,

        charge_limit_is_active:
            chargeLimitActive,

        charge_limit_reason:
            chargeLimitReason,

        modbus_mode_reason:
            modeReason,

        storctl_mod_proposed:
            storctl,

        outwrte_proposed:
            outwrte,

        inwrte_proposed:
            inwrte,

        sunrise_min:
            sunriseMinutes,

        discharge_start_min:
            dischargeStart,

        discharge_end_min:
            dischargeEnd,

        charge_block_start_min:
            chargeBlockStart,

        charge_block_end_min:
            chargeBlockEnd
    };


    for (
        const [
            key,
            value
        ]
        of Object.entries(
            values
        )
    ) {

        flow.set(
            "strategy_v7_" +
            key,
            value
        );
    }


    flow.set(
        "storctl_mod",
        storctl
    );


    flow.set(
        "outwrte",
        outwrte
    );


    flow.set(
        "inwrte",
        inwrte
    );
}


// ======================================================
// WRITE ACTIVE
// ======================================================

const writeActive =

    !sim

    &&

    socValid

    &&

    Number.isFinite(
        storctl
    )

    &&

    Number.isFinite(
        outwrte
    )

    &&

    Number.isFinite(
        inwrte
    );


// ======================================================
// OUTPUT
// ======================================================

msg.payload = {

    ok:

        socValid

        &&

        todayForecastValid,


    mode:

        sim

            ? "simulation_v7_3"

            : "v7_3_dynamic_sunrise",


    simulation: {

        active:
            sim,

        write_suppressed:
            sim
    },


    time: {

        vienna_now:

            sim

                ? (
                    "SIM " +
                    hhmm(
                        nowMinutes
                    )
                )

                : viennaDateTime(),


        minutes:
            nowMinutes,


        hhmm:
            hhmm(
                nowMinutes
            ),


        sunrise:

            sunriseMinutes ===
            null

                ? null

                : hhmm(
                    sunriseMinutes
                ),


        sunrise_minutes:
            sunriseMinutes,


        sunrise_source:
            sunriseSource,


        in_discharge_window:
            inDischargeWindow,


        discharge_start:
            hhmm(
                dischargeStart
            ),


        discharge_end:
            hhmm(
                dischargeEnd
            ),


        discharge_end_offset_min:
            DISCHARGE_END_OFFSET_MIN,


        discharge_window:

            hhmm(
                dischargeStart
            )

            +

            "-"

            +

            hhmm(
                dischargeEnd
            ),


        charge_block_start:
            hhmm(
                chargeBlockStart
            ),


        charge_block_end:
            hhmm(
                chargeBlockEnd
            ),


        charge_block_window:

            hhmm(
                chargeBlockStart
            )

            +

            "-"

            +

            hhmm(
                chargeBlockEnd
            )
    },


