        "netz_w",
        "netzbezug_w",
        "p_grid",
        "P_Grid",
        "grid_w"
    ]),

    battery_power_w: findValue(root, [
        "battery_power_w",
        "battery_power",
        "batterie_w",
        "p_battery",
        "P_Battery"
    ])
};

// Keine alten gültigen Werte mit null überschreiben
const old = flow.get("verto_gui_live") || {};

const merged = {
    ...old,
    ...Object.fromEntries(
        Object.entries(live).filter(([k, v]) => k === "updated_at" || v !== null)
    )
};

flow.set("verto_gui_live", merged);

node.status({
    fill: "green",
    shape: "dot",
    text: `SOC ${merged.soc_percent ?? "?"}% | Haus ${merged.house_load_w ?? "?"} W`
});

msg.payload = merged;
return msg;

// ======================================================
// NODE: GUI Status bauen V7.3
//
// Keine eigene Strategielogik.
// Strategie_V7 ist die einzige Strategiequelle.
// ======================================================

function num(...values) {

    for (
        const value
        of values
    ) {

        if (
            value === null ||
            value === undefined ||
            value === ""
        ) {
            continue;
        }


        const n =
            Number(
                value
            );


        if (
            Number.isFinite(
                n
            )
        ) {

            return n;
        }
    }


    return null;
}


function text(...values) {

    for (
        const value
        of values
    ) {

        if (
            value !== undefined &&
            value !== null &&
            String(value).trim() !== ""
        ) {

            return String(
                value
            );
        }
    }


    return null;
}


function prettyReason(
    raw
) {

    const r =
        String(
            raw || ""
        )
        .trim();


    const map = {

        dynamic_discharge_to_target_by_discharge_end:
