        strategic_discharge_disabled:
            "Strategische Morgenentladung ist deaktiviert.",

        forecast_invalid_no_strategic_discharge:
            "Keine gültige Prognose. Keine strategische Entladung.",

        sunrise_charge_block_active:
            "Das Aufladen des Akkus ist im Morgen-Ladeblock gesperrt.",

        outside_charge_block_window:
            "Außerhalb des Zeitfensters für die Aufladeblockierung.",

        charge_block_disabled:
            "Aufladeblockierung ist deaktiviert.",

        soc_too_low_no_charge_block:
            "SOC zu niedrig. Das Aufladen des Akkus bleibt erlaubt.",

        today_forecast_too_low_no_charge_block:
            "Heutige Prognose zu niedrig für die Aufladeblockierung.",

        very_good_forecast:
            "Sehr gute heutige Prognose: Ladeleistung stark begrenzt.",

        good_forecast:
            "Gute heutige Prognose: Ladeleistung begrenzt.",

        medium_forecast:
            "Mittlere heutige Prognose: Ladeleistung moderat begrenzt.",

        weak_forecast:
            "Schwache heutige Prognose: volle Ladeleistung erlaubt.",

        charge_limit_disabled:
            "Prognoseabhängige Ladebegrenzung ist deaktiviert.",

        entladen_sperren_aktiv:
            "Entladesperre aktiv. Verto übernimmt die Speicherregelung.",

        external_discharge_lock:
            "Externe Entladesperre aktiv."
    };


    if (
        map[r]
    ) {

        return map[r];
    }


    if (
        r.includes(
            "_"
        )
    ) {

        return r.replaceAll(
            "_",
            " "
        );
    }


    return r ||
        "Strategiedaten empfangen.";
}


const src =

