const live =
    flow.get(
        "verto_gui_live"
    )
    ||
    {};


const config =
    flow.get(
        "strategy_v7_config"
    )
    ||
    null;


const inputs =
    src.inputs ||
    {};


const reserve =
    src.reserve ||
    {};


const chargeLimit =
    src.charge_limit ||
    {};


const chargeBlock =
    src.charge_block ||
    {};


const strategic =
    src.strategic_discharge ||
