function clone(
    value
) {

    return JSON.parse(
        JSON.stringify(
            value
        )
    );
}


function isObj(
    value
) {

    return (
        value &&
        typeof value ===
        "object" &&
        !Array.isArray(
            value
        )
    );
}


function deepMerge(
    defaults,
    existing
) {

    if (
        !isObj(
            defaults
        )
    ) {

        return existing !==
        undefined

            ? existing

            : defaults;
    }


    const result =
        {};


    for (
        const key
        of Object.keys(
            defaults
        )
    ) {

        const d =
            defaults[key];


        const e =

            isObj(
                existing
            )

            &&

            Object.prototype.hasOwnProperty.call(
                existing,
                key
            )

                ? existing[key]

                : undefined;


        result[key] =

            isObj(d)

                ? deepMerge(
                    d,
                    e
                )

                : (
                    e !==
                    undefined

                        ? e

                        : d
                );
    }


    if (
        isObj(
            existing
        )
    ) {

        for (
            const key
            of Object.keys(
                existing
            )
        ) {

            if (
                !(key in result)
            ) {

                result[key] =
                    existing[key];
            }
        }
    }


    return result;
}


function finite(
    value
) {

    const n =
        Number(
            value
        );


    return Number.isFinite(
        n
    )

        ? n

        : null;
}


