function setNested(
    obj,
    path,
    value
) {

    const parts =
        path.split(".");


    let cur =
        obj;


    for (
        let i = 0;
        i < parts.length - 1;
        i++
    ) {

        if (
            !cur[
                parts[i]
            ] ||
            typeof cur[
                parts[i]
            ] !==
            "object"
        ) {

            cur[
                parts[i]
            ] =
                {};
        }


        cur =
            cur[
                parts[i]
            ];
    }


    cur[
        parts[
            parts.length - 1
        ]
    ] =
        value;
}


function getNested(
    obj,
    path
) {

    let cur =
        obj;


    for (
        const key
        of path.split(".")
    ) {

        if (
            cur === null ||
            cur === undefined ||
            typeof cur !==
            "object"
        ) {

            return undefined;
        }


        cur =
            cur[key];
    }


    return cur;
}


function normalize(
    path,
    value
) {

    const rule =
        rules[path];


    if (
        !rule
    ) {

        return {

            ok:
                false,

            error:
                "Unbekannter oder nicht erlaubter Config-Pfad: " +
                path
        };
    }


    if (
        value === null ||
        value === undefined ||
        value === ""
    ) {

        return rule.nullable

            ? {

                ok:
                    true,

                value:
                    null
            }

            : {

                ok:
                    false,

                error:
                    path +
                    " darf nicht leer sein"
            };
    }


    if (
        rule.type ===
        "number"
    ) {

        const n =
            Number(
                value
            );


        if (
            !Number.isFinite(
                n
            )
        ) {

            return {

                ok:
                    false,

                error:
                    path +
                    " ist keine gültige Zahl"
            };
        }


        if (
            n < rule.min ||
            n > rule.max
        ) {

            return {

                ok:
                    false,

                error:

                    path +
                    " muss zwischen " +
                    rule.min +
                    " und " +
                    rule.max +
                    " liegen"
            };
        }


        return {

            ok:
                true,

            value:
                n
        };
    }


    if (
        rule.type ===
        "boolean"
    ) {

        if (
            value === true ||
            value === false
        ) {

            return {

                ok:
                    true,

                value:
                    value
            };
        }


        if (
            [
                1,
                "1",
                "true",
                "on"
            ]
            .includes(
                value
            )
        ) {

            return {

                ok:
                    true,

                value:
                    true
            };
        }


        if (
            [
                0,
                "0",
                "false",
                "off"
            ]
            .includes(
                value
            )
        ) {

            return {

                ok:
                    true,

                value:
                    false
            };
        }


        return {

            ok:
                false,

            error:
                path +
                " ist kein gültiger Ein/Aus-Wert"
        };
    }


    return {

        ok:
            false,

        error:
            "Unbekannter Datentyp für " +
            path
    };
}


function cleanLegacy(
    cfg
) {

    if (
        cfg.reserve
    ) {

        delete cfg
            .reserve
            .tomorrow_bad_below_kwh;

        delete cfg
            .reserve
            .target_soc_bad;

        delete cfg
            .reserve
            .tomorrow_weak_below_kwh;

        delete cfg
            .reserve
            .tomorrow_medium_below_kwh;

        delete cfg
            .reserve
            .today_weak_below_kwh;

        delete cfg
            .reserve
            .today_weak_target_soc;
    }


    if (
        cfg.charge_block
    ) {

        delete cfg
            .charge_block
            .min_tomorrow_kwh;
    }


    if (
        cfg.charge_limit
    ) {

        delete cfg
            .charge_limit
            .very_good_tomorrow_min_kwh;

        delete cfg
            .charge_limit
            .good_tomorrow_min_kwh;

        delete cfg
            .charge_limit
            .medium_tomorrow_min_kwh;
    }
}


function validate(
    cfg
) {

    const errors =
        [];


    const veryBad =
        Number(
            cfg.reserve.very_bad_below_kwh
        );


    const weak =
        Number(
            cfg.reserve.weak_below_kwh
        );


    const medium =
        Number(
            cfg.reserve.medium_below_kwh
        );


    if (
        !(
            veryBad < weak &&
            weak < medium
        )
    ) {

        errors.push(
            "Reserve: Schwellen müssen aufsteigend sein: SEHR SCHLECHT < SCHWACH < MITTEL."
        );
    }


    const minSoc =
        Number(
            cfg.reserve.min_soc_absolute
        );


    const targets = [

        [
            "SEHR SCHLECHT",
            cfg.reserve.target_soc_very_bad
        ],

        [
            "SCHWACH",
            cfg.reserve.target_soc_weak
        ],

        [
            "MITTEL",
            cfg.reserve.target_soc_medium
        ],

        [
            "GUT",
            cfg.reserve.target_soc_good
        ]
    ];


    for (
        const [
            name,
            soc
        ]
        of targets
    ) {

        if (
            Number(soc) <
            minSoc
        ) {

            errors.push(

                name +
                " Ziel-SOC (" +
                soc +
                "%) liegt unter min_soc_absolute (" +
                minSoc +
                "%)."
            );
        }
    }


    const vg =
        Number(
            cfg.charge_limit.very_good_today_min_kwh
        );


    const good =
        Number(
            cfg.charge_limit.good_today_min_kwh
        );


    const med =
        Number(
            cfg.charge_limit.medium_today_min_kwh
        );


    if (
        !(
            vg >= good &&
            good >= med
        )
    ) {

        errors.push(
            "Ladebegrenzung: Schwellen müssen absteigend sein: VERY GOOD >= GOOD >= MEDIUM."
        );
    }


    if (
        Number(
            cfg.discharge.max_power_w
        )
        >
        Number(
            cfg.battery.power_ref_w
        )
    ) {

        errors.push(
            "Max. strategische Entladeleistung darf nicht größer als battery.power_ref_w sein."
        );
    }


    return errors;
}


const topic =
    String(
        msg.topic
        ??
        ""
    )
    .trim();


const next =
    clone(
        config
    );


cleanLegacy(
    next
);


const changedFields =
    [];


if (
    topic ===
    "gui/strategy_config"

    ||

    topic ===
    "strategy_v7_config"
) {

    const incoming =
        msg.payload;


    if (
        !incoming ||
        typeof incoming !==
        "object" ||
        Array.isArray(
            incoming
        )
    ) {

        msg.payload = {

            ok:
                false,

            error:
                "GUI Config muss ein Objekt sein."
        };


        node.status({

            fill:
                "red",

            shape:
                "ring",

            text:
                "GUI Config ungültig"
        });


        return msg;
    }


    for (
        const path
        of Object.keys(
            rules
        )
    ) {

        const value =
            getNested(
                incoming,
                path
            );


        if (
            value ===
            undefined
        ) {

            continue;
        }


        const r =
            normalize(
                path,
                value
            );


        if (
            !r.ok
        ) {

            msg.payload = {

                ok:
                    false,

                error:
                    r.error,

                field:
                    path
            };


            node.status({

                fill:
                    "red",

                shape:
                    "ring",

                text:
                    "Config Fehler: " +
                    path
            });


            return msg;
        }


        setNested(
            next,
            path,
            r.value
        );


        changedFields.push({

            path:
                path,

            value:
                r.value
        });
    }
}

else {

    if (
        !topic
    ) {

        msg.payload = {

            ok:
                false,

            error:
                "msg.topic fehlt"
        };


        return msg;
    }


    const r =
        normalize(
            topic,
            msg.payload
        );


    if (
        !r.ok
    ) {

        msg.payload = {

            ok:
                false,

            error:
                r.error,

            field:
                topic
        };


        node.status({

            fill:
                "red",

            shape:
                "ring",

            text:
                "Config Fehler"
        });


        return msg;
    }


    setNested(
        next,
        topic,
        r.value
    );


    changedFields.push({

        path:
            topic,

        value:
            r.value
    });
}


